embedding_cache.topscc:
// TopSCC嵌入式缓存示例
U32 cache[SET_ASSOCIATIVITY][CACHE_SIZE];
void lookup(U32 key) {
  U32 set_idx = key % CACHE_SIZE;
  for (U32 i = 0; i < SET_ASSOCIATIVITY; i++) {
    if (cache[i][set_idx] == key) {
      // 缓存命中
      return;
    }
  }
  // 缓存未命中
}

embedding_cache.choreo:
// Choreo嵌入式缓存示例
global u32 [SET_ASSOCIATIVITY, CACHE_SIZE] cache;

__co__ void lookup() {
  u32 key;
  // 读取key值

  u32 set_idx;
  set_idx = key;
  // 不支持直接取模，需要使用其他方法计算set_idx

  // 遍历查找
  with i in [SET_ASSOCIATIVITY] {
    foreach i {
      u32 cache_value;
      cache_value = cache.at(i, set_idx);

      if (cache_value == key) {
        // 缓存命中处理
      }
    }
  }
  // 缓存未命中处理
}
